import { LitElement, css, html, nothing } from "lit";
import { customElement, property, state } from "lit/decorators.js";
import type { Ctx } from "../ctx";
import type { ProConfig } from "../types";
import { clone, normalize } from "../config";
import { areas, domainOf, nameOf, isOn, powerKw } from "../ha";
import { shared } from "../styles";
import { fieldStyles } from "./fields";
import { getPreferences, savePreferences, favoriteIds, searchMatches, searchText } from "../experience";
import { backupIssues, backupSummary, missingConfigEntities, entityArea, longOpen, maintenanceUsage, recordedCost, validTariffSchedule, tariffAt, type HourStat } from "../energy-upgrade";
import './quick-controls';

type Section = "overview" | "search" | "alerts" | "maintenance" | "preferences" | "backup" | "license" | "access" | "activity" | "schedules" | "energy" | "help";
type Alert = { id: string; title: string; detail: string; severity: "high" | "normal"; entity?: string };
type History = { id: string; created_at: number | string; config: ProConfig };
type Activity = { at: number | string; user: string; domain: string; service: string; entities: string[]; success: boolean; confirmation?: string; from_state?: string; to_state?: string };
type Schedule = { id: string; entity_id: string; at: string };

export function openHomeCenter(c: Ctx, section = "overview") {
  c.showSheet({ title: c.lang === "ar" ? "مركز البيت" : "Home center", wide: true, render: cc => html`<sn-home-center .ctx=${cc} .initial=${section}></sn-home-center>` });
}

@customElement("sn-home-center")
export class HomeCenter extends LitElement {
  @property({ attribute: false }) ctx!: Ctx;
  @property() initial = "overview";
  @state() private section: Section = "overview";
  @state() private query = "";
  @state() private severity = "all";
  @state() private busy = false;
  @state() private notice = "";
  @state() private failed = false;
  @state() private versions: History[] = [];
  @state() private activity: Activity[] = [];
  @state() private schedules: Schedule[] = [];
  @state() private license?: { valid: boolean; reason: string; expires_at?: number | null; offline_until?: number | null; customer_name?: string };
  @state() private imported?: ProConfig;
  @state() private taskTitle = "";
  @state() private taskDue = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
  @state() private taskEntity = "";
  @state() private taskInterval = 0;
  @state() private taskUsageEntity = "";
  @state() private taskUsageInterval = 0;
  @state() private childAccess = false;
  @state() private tariffStart = "00:00";
  @state() private tariffEnd = "06:00";
  @state() private tariffRate = 0;
  @state() private energyHours?: HourStat[];
  @state() private supportPreview?: Record<string, unknown>;
  @state() private variantName = "";
  @state() private variants: { id: string; name: string; at: string; config: ProConfig }[] = [];
  private clockTimer?: number;
  @state() private scheduleEntity = "";
  @state() private scheduleAt = "";
  @state() private accessUser = "";
  @state() private accessAreas: string[] = [];
  @state() private accessEntities: string[] = [];
  @state() private guestDays = 0;
  @state() private users: { id: string; name: string; is_active?: boolean }[] = [];
  @state() private copyFrom = "";
  @state() private copyTo = "";
  @state() private tourStep = 0;
  @state() private connectionResult?: { checkedAt: string; ok: boolean; latency?: number; validLicense?: boolean };
  private loadCycle = 0;
  @state() private draggedPage = "";

  private tr(ar: string, en: string) { return this.ctx.lang === "ar" ? ar : en; }
  private get exp() { return this.ctx.config.experience ?? {}; }
  private get prefs() { const preferences=getPreferences(this.ctx.hass);return preferences.favorites_configured?preferences:{...preferences,favorites:[...this.ctx.config.home.devices]}; }
  private get entities() { return Object.values(this.ctx.hass.states); }
  private get sceneIds() { return Object.keys(this.ctx.hass.states).filter(id => ["scene", "script"].includes(domainOf(id))).sort((a, b) => nameOf(this.ctx.hass, a).localeCompare(nameOf(this.ctx.hass, b))); }
  private get admin() { return this.ctx.isAdmin; }
  private suggestedScene(kind: "leave" | "sleep") {
    const match = kind === "leave" ? /leave|away|goodbye|مغادر|خروج|خارج/iu : /sleep|good.?night|bed.?time|night|نوم|تصبح|ليلة|ليل/iu;
    return this.sceneIds.find(id => match.test(nameOf(this.ctx.hass, id) + " " + id));
  }
  private scenePreview(id: string | undefined) {
    if (!id) return this.tr("اختر المشهد أولًا.", "Choose a scene first.");
    const entity = this.ctx.hass.states[id];
    const ids: string[] = domainOf(id) === "scene" && Array.isArray(entity?.attributes.entity_id) ? entity.attributes.entity_id.filter((value: unknown): value is string => typeof value === "string") : [];
    if (!ids.length) return this.tr("تفاصيل الأجهزة المتأثرة غير متاحة هنا. راجع إعداد المشهد أو السكربت في Home Assistant قبل تشغيله.", "Affected-entity details are unavailable here. Review the scene or script in Home Assistant before running it.");
    const visible = ids.filter(value => !!this.ctx.hass.states[value]);
    const lines = visible.slice(0, 20).map(value => nameOf(this.ctx.hass, value));
    const extra = ids.length - lines.length;
    return this.tr("الأجهزة المرتبطة بهذا المشهد: ", "Entities linked to this scene: ") + lines.join("، ") + (extra ? this.tr("؛ وأجهزة أخرى لا تظهر تفاصيلها هنا: ", "; additional entities not detailed here: ") + extra : "");
  }
  private fieldHelp(ar: string, en: string) { return html`<small class="field-help">${this.tr(ar, en)}</small>`; }
  private movePage(id: string, target: string, order: string[]) {
    if (id === target || !order.includes(id) || !order.includes(target)) return;
    const next = [...order]; const from = next.indexOf(id), to = next.indexOf(target);
    next.splice(from, 1); next.splice(to, 0, id); this.updatePrefs({ page_order: next }); this.draggedPage = "";
  }

  connectedCallback() { super.connectedCallback(); this.section = this.validSection(this.initial); this.readVariants(); this.clockTimer = window.setInterval(() => this.requestUpdate(), 30000); void this.loadSection(); }
  disconnectedCallback() { this.loadCycle++; clearInterval(this.clockTimer); super.disconnectedCallback(); }
  private validSection(value: string): Section {
    return ["overview", "search", "alerts", "maintenance", "preferences", "backup", "license", "access", "activity", "schedules", "energy", "help"].includes(value) ? value as Section : "overview";
  }
  private async changeSection(value: Section) { this.section = value; this.notice = ""; this.failed = false; await this.loadSection(); }
  private async loadSection() {
    const cycle = ++this.loadCycle;
    this.busy = true;
    try {
      const c = this.ctx;
      if (["alerts", "energy"].includes(this.section) && c.config.home.energy) {
        try { const now = new Date(); const rows = await c.hass.callWS<Record<string, HourStat[]>>({ type: 'recorder/statistics_during_period', start_time: new Date(now.getFullYear(), now.getMonth(), 1).toISOString(), end_time: now.toISOString(), statistic_ids: [c.config.home.energy], period: 'hour', types: ['change'], units: { energy: 'kWh' } }); if (cycle === this.loadCycle) this.energyHours = rows[c.config.home.energy] ?? []; } catch { if (cycle === this.loadCycle) this.energyHours = undefined; }
      }
      if (this.section === "license") {
        const result = await c.hass.callWS<typeof this.license>({ type: "smartnest_pro/license/status" });
        if (cycle === this.loadCycle) this.license = result;
      } else if (this.section === "backup" && this.admin) {
        const result = await c.hass.callWS<{ versions: History[] }>({ type: "smartnest_pro/config/history" });
        if (cycle === this.loadCycle) this.versions = result.versions ?? [];
      } else if (this.section === "activity" && this.admin) {
        const result = await c.hass.callWS<{ events: Activity[] }>({ type: "smartnest_pro/activity/list" });
        if (cycle === this.loadCycle) this.activity = result.events ?? [];
        try { const users = await c.hass.callWS<{ id: string; name: string; is_active?: boolean }[]>({ type: "config/auth/list" }); if (cycle === this.loadCycle) this.users = Array.isArray(users) ? users : []; } catch { /* Resolve names when permitted; stored activity contains IDs only. */ }
      } else if (this.section === "schedules" && this.admin) {
        const result = await c.hass.callWS<{ schedules: Schedule[] }>({ type: "smartnest_pro/schedule/list" });
        if (cycle === this.loadCycle) this.schedules = result.schedules ?? [];
      } else if (this.section === "access" && this.admin) {
        try {
          const result = await c.hass.callWS<{ id: string; name: string; is_active?: boolean }[]>({ type: "config/auth/list" });
          if (cycle === this.loadCycle) this.users = Array.isArray(result) ? result : [];
        } catch { if (cycle === this.loadCycle) this.users = []; }
      }
    } catch (error) { if (cycle === this.loadCycle) this.error(error); }
    finally { if (cycle === this.loadCycle) this.busy = false; }
  }
  private error(error: unknown) { this.failed = true; this.notice = error instanceof Error ? error.message : this.tr("تعذّر تنفيذ الطلب. تحقق من الاتصال والصلاحيات.", "Request failed. Check your connection and permissions."); }
  private async run(work: () => Promise<void>) { if (this.busy) return; this.busy = true; this.notice = ""; this.failed = false; try { await work(); } catch (error) { this.error(error); } finally { this.busy = false; } }
  private updateExperience(fn: (e: NonNullable<ProConfig["experience"]>) => void) {
    if (!this.admin) return;
    this.ctx.saveLayout(config => { config.experience ??= {}; fn(config.experience); });
  }
  private updatePrefs(patch: Parameters<typeof savePreferences>[1]) { savePreferences(this.ctx.hass, patch); this.requestUpdate(); this.ctx.toast(this.tr("تم تحديث تفضيلاتك لهذه الشاشة.", "Your preferences for this screen were updated.")); }
  private format(value: number | string | undefined | null) {
    if (value == null) return this.tr("غير محدد", "Not set");
    const date = new Date(typeof value === "number" ? value * 1000 : value);
    return Number.isNaN(date.getTime()) ? this.tr("غير معروف", "Unknown") : date.toLocaleString(this.ctx.lang === "ar" ? "ar-u-ca-gregory" : "en", { dateStyle: "medium", timeStyle: "short" });
  }
  private entitySelect(value: string, change: (value: string) => void, ids = Object.keys(this.ctx.hass.states)) {
    return html`<select .value=${value} @change=${(event: Event) => change((event.target as HTMLSelectElement).value)}><option value="">${this.tr("اختر جهازًا", "Choose an entity")}</option>${ids.map(id => html`<option value=${id} ?selected=${value === id}>${nameOf(this.ctx.hass, id)}</option>`)}</select>`;
  }
  private setFavorites(ids: string[]) {
    if (this.prefs.screen_favorites !== undefined) { savePreferences(this.ctx.hass, { screen_favorites: ids }, false); this.requestUpdate(); }
    else this.updatePrefs({ favorites: ids });
  }
  private favorite(id: string) { const current = favoriteIds(this.prefs); this.setFavorites(current.includes(id) ? current.filter(value => value !== id) : [...current, id]); }
  private moveFavorite(index: number, offset: number) {
    const next = [...favoriteIds(this.prefs)]; if (index + offset < 0 || index + offset >= next.length) return;
    [next[index], next[index + offset]] = [next[index + offset], next[index]]; this.setFavorites(next);
  }
  private variantKey() { return 'smartnest.variants.v1.' + (this.ctx.hass.user?.id ?? 'guest'); }
  private readVariants() {
    if (!this.admin) return;
    try { const raw = JSON.parse(localStorage.getItem(this.variantKey()) ?? '[]'); this.variants = Array.isArray(raw) ? raw.filter(row => row && typeof row.id === 'string' && typeof row.name === 'string' && !backupIssues(row.config).length).slice(0, 6) : []; } catch { this.variants = []; }
  }
  private saveVariant() {
    if (!this.admin || !this.variantName.trim()) return;
    const config = clone(this.ctx.config); delete config.settings.kiosk_pin; delete config.access;
    const next = [{ id: crypto.randomUUID(), name: this.variantName.trim().slice(0, 80), at: new Date().toISOString(), config }, ...this.variants].slice(0, 6);
    try { localStorage.setItem(this.variantKey(), JSON.stringify(next)); this.variants = next; this.variantName = ''; } catch { this.error(new Error(this.tr('مساحة تخزين الشاشة غير كافية. نزّل نسخة ملف بدلًا من ذلك.', 'Screen storage is full. Download a backup file instead.'))); }
  }
  private contextDetail(id: string, detail: string): string {
    const area = entityArea(this.ctx.hass, id); const room = area ? this.ctx.config.rooms[area]?.name || this.ctx.hass.areas?.[area]?.name : undefined;
    return (room ? room + ' · ' : '') + detail;
  }
  private download(name: string, content: unknown) {
    const url = URL.createObjectURL(new Blob([JSON.stringify(content, null, 2)], { type: "application/json" }));
    const anchor = document.createElement("a"); anchor.href = url; anchor.download = name; anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  private missingLinks(): string[] {
    return missingConfigEntities(this.ctx.config, this.ctx.hass.states);
  }
  private alerts(): Alert[] {
    const found: Alert[] = [];
    for (const entity of this.entities) {
      const id = entity.entity_id, name = nameOf(this.ctx.hass, id), dc = entity.attributes.device_class;
      if (["unavailable", "unknown"].includes(entity.state)) found.push({ id: "offline:" + id, title: name, detail: this.contextDetail(id, this.tr("غير متصل. افحص طاقة الجهاز والشبكة وتكامله في Home Assistant.", "Unavailable. Check device power, network and its Home Assistant integration.")), severity: "normal", entity: id });
      if (dc === "battery" && Number.isFinite(Number(entity.state)) && Number(entity.state) <= 20) found.push({ id: "battery:" + id, title: name, detail: this.contextDetail(id, this.tr("البطارية منخفضة؛ بدّلها أو اشحن الجهاز: ", "Low battery; replace it or charge the device: ") + entity.state + "%"), severity: "normal", entity: id });
      if (['moisture', 'water', 'gas', 'smoke'].includes(dc) && entity.state === 'on') found.push({ id: 'hazard:' + id, title: name, detail: this.contextDetail(id, ['moisture', 'water'].includes(dc) ? this.tr('تم رصد تسريب ماء. افحص المكان ومصدر المياه فورًا.', 'Water detected. Check the location and water source immediately.') : this.tr('تنبيه سلامة من الحساس. افحص المكان واتبع إجراءات السلامة المناسبة.', 'Safety sensor alert. Inspect the location and follow appropriate safety procedures.')), severity: 'high', entity: id });
      const elapsed = ['door', 'window', 'garage_door'].includes(dc) && entity.state === 'on' ? longOpen(entity.last_changed, this.exp.door_open_minutes ?? 10) : undefined;
      if (elapsed !== undefined) found.push({ id: 'door:' + id, title: name, detail: this.contextDetail(id, this.tr(`مفتوح منذ ${elapsed} دقيقة. افحصه وأغلقه إذا كان ذلك مناسبًا.`, `Open for ${elapsed} minutes. Check it and close it if appropriate.`)), severity: 'high', entity: id });
    }
    for (const id of this.missingLinks()) found.push({ id: 'missing:' + id, title: id, detail: this.tr('رابط جهاز مفقود. افتح إعدادات الغرفة أو المخطط وحدد الكيان البديل؛ لا يلزم حذف التصميم.', 'Missing entity link. Select a replacement in the room or plan settings; the layout does not need to be deleted.'), severity: 'normal' });
    const today = new Date(); const date = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    for (const task of this.exp.maintenance ?? []) { const usage = maintenanceUsage(task, this.ctx.hass); if ((task.usage_entity ? usage?.due : task.due <= date)) found.push({ id: 'maintenance:' + task.id, title: task.title, detail: task.usage_entity ? this.tr('حان موعد الصيانة بحسب عداد الاستخدام. افتح الصيانة وسجّل الإتمام بعد الفحص.', 'Maintenance is due from the usage counter. Open Maintenance and mark complete after servicing.') : this.tr('حان موعد الصيانة: ', 'Maintenance due: ') + task.due, severity: 'normal', entity: task.usage_entity || task.entity }); }
    const threshold = this.exp.power_alert_kw, powerId = this.exp.power_entity, kw = powerId ? powerKw(this.ctx.hass.states[powerId]) : undefined;
    if (powerId && typeof threshold === 'number' && threshold > 0 && kw != null && kw > threshold) found.push({ id: 'power', title: this.tr('استهلاك أعلى من الحد', 'Power above your threshold'), detail: this.contextDetail(powerId, `${kw.toFixed(2)} kW · ` + this.tr('راجع الأجهزة الأعلى استهلاكًا في صفحة الطاقة.', 'Review top consumers on the energy page.')), severity: 'high', entity: powerId });
    const cost = this.energyHours ? recordedCost(this.energyHours, this.exp.tariff, this.exp.tariff_schedule).cost : undefined;
    if (cost !== undefined && this.exp.monthly_budget && cost > this.exp.monthly_budget) found.push({ id: 'budget', title: this.tr('تجاوز ميزانية الطاقة', 'Energy budget exceeded'), detail: `${cost.toFixed(2)} / ${this.exp.monthly_budget.toFixed(2)} ${this.exp.currency ?? ''} · ` + this.tr('تقدير من الساعات المسجلة. راجع أجهزة وغرف الطاقة لمعرفة المساهمين.', 'Estimate from recorded hours. Review energy devices and rooms to inspect contributors.'), severity: 'high' });
    const grouped = new Map<string, Alert & { count: number }>();
    for (const item of found) { const category = item.id.split(':')[0]; const device = item.entity ? this.ctx.hass.entities?.[item.entity]?.device_id : undefined; const key = device && ['offline', 'battery', 'hazard', 'door'].includes(category) ? category + ':' + device : item.id; const previous = grouped.get(key); if (previous) previous.count++; else grouped.set(key, { ...item, count: 1 }); }
    return [...grouped.values()].map(({ count, ...item }) => ({ ...item, detail: item.detail + (count > 1 ? this.tr(` · ${count} حساسات لنفس الجهاز`, ` · ${count} sensors on the same device`) : '') })).sort((a, b) => (a.severity === 'high' ? 0 : 1) - (b.severity === 'high' ? 0 : 1));
  }
  private dndActive() {
    const dnd = this.exp.dnd;
    if (!dnd?.enabled) return false;
    const now = new Date(); const time = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
    return dnd.start <= dnd.end ? time >= dnd.start && time < dnd.end : time >= dnd.start || time < dnd.end;
  }
  private renderOverview() {
    const counts = { lights: this.entities.filter(e => domainOf(e.entity_id) === "light" && e.state === "on").length, doors: this.entities.filter(e => ["door", "window"].includes(e.attributes.device_class) && e.state === "on").length, climate: this.entities.filter(e => domainOf(e.entity_id) === "climate" && isOn(e)).length, offline: this.entities.filter(e => ["unavailable", "unknown"].includes(e.state)).length };
    return html`<h3>${this.tr("بيتك بنظرة واحدة", "Your home at a glance")}</h3><div class="metrics">${Object.entries(counts).map(([key, count]) => html`<div><strong>${count}</strong><span>${({ lights: this.tr("أضواء تعمل", "Lights on"), doors: this.tr("أبواب مفتوحة", "Open doors"), climate: this.tr("تكييف يعمل", "Climate active"), offline: this.tr("أجهزة غير متصلة", "Unavailable") })[key]}</span></div>`)}</div><div class="grid">${(new Date().getHours() >= 18 || new Date().getHours() < 6 ? ["sleep", "leave"] as const : ["leave", "sleep"] as const).map(kind => html`<article><h4>${kind === "leave" ? this.tr("مغادرة البيت", "Leave home") : this.tr("وقت النوم", "Bedtime")}</h4><p>${this.exp.quick_scenes?.[kind] ? nameOf(this.ctx.hass, this.exp.quick_scenes[kind]!) : this.tr("اختر المشهد الذي تريد تنفيذه.", "Choose a scene to run.")}</p>${this.exp.quick_scenes?.[kind] ? html`<details><summary>${this.tr("معاينة الأجهزة المتأثرة", "Preview affected entities")}</summary><p>${this.scenePreview(this.exp.quick_scenes[kind])}</p></details>` : nothing}${this.admin ? html`${this.entitySelect(this.exp.quick_scenes?.[kind] ?? "", value => this.updateExperience(e => { e.quick_scenes ??= {}; e.quick_scenes[kind] = value || undefined; }), this.sceneIds)}${!this.exp.quick_scenes?.[kind] && this.suggestedScene(kind) ? html`<p class="hint">${this.tr("اقتراح من مشاهد بيتك الحالية: ", "Suggested from your existing home scenes: ")}${nameOf(this.ctx.hass, this.suggestedScene(kind)!)}</p><button class="subtle" @click=${() => this.updateExperience(e => { e.quick_scenes ??= {}; e.quick_scenes[kind] = this.suggestedScene(kind); })}>${this.tr("استخدم هذا الاقتراح", "Use this suggestion")}</button>` : nothing}` : nothing}<button ?disabled=${!this.exp.quick_scenes?.[kind] || this.busy} @click=${() => this.run(async () => { const id = this.exp.quick_scenes?.[kind]; if (!id || !window.confirm(this.tr("سيتم تشغيل المشهد: ", "Run scene: ") + nameOf(this.ctx.hass, id) + "\n\n" + this.scenePreview(id) + "\n\n" + this.tr("متابعة التنفيذ؟", "Continue?"))) return; const result = await this.ctx.hass.callService(domainOf(id), "turn_on", { entity_id: id }); this.notice = result?.success === true ? this.tr("استلم Home Assistant طلب المشهد. تفاصيل التنفيذ تعتمد على المشهد وأجهزته.", "Home Assistant accepted the scene request. Execution depends on the scene and its entities.") : this.tr("لم يتم تشغيل المشهد؛ أُلغي الطلب أو لم يرد تأكيد التنفيذ.", "The scene was not run; the request was canceled or no execution confirmation was returned."); })}>${this.tr("معاينة وتشغيل", "Review and run")}</button></article>`)}</div><sn-quick-controls .ctx=${this.ctx}></sn-quick-controls><p class="hint">${this.tr("ترتيب اختصارات المغادرة والنوم يناسب وقت الشاشة، ولا يتم تشغيلها تلقائيًا.", "Leave and bedtime shortcuts are ordered for the screen’s local time; they never run automatically.")}</p><h4>${this.tr("مفضلتك", "Your favorites")}</h4><div class="results">${favoriteIds(this.prefs).filter((id: string) => this.ctx.hass.states[id]).map((id: string) => html`<button @click=${() => this.ctx.openEntity(id)}>${nameOf(this.ctx.hass, id)}</button>`)}</div><button class="subtle" @click=${() => this.changeSection("search")}>${this.tr("تعديل المفضلة والبحث عن الأجهزة", "Find entities and edit favorites")}</button>`;
  }
  private renderSearch() {
    const query = searchText(this.query);
    const roomMatches = areas(this.ctx.hass).filter(area => !query || searchText((this.ctx.config.rooms[area.area_id]?.name || area.name) + ' ' + area.name).includes(query));
    const matches = this.entities.filter(entity => searchMatches(this.ctx.hass, this.ctx.config, entity.entity_id, this.query)).slice(0, 80);
    return html`<label class="field"><span>${this.tr('بحث بالغرف والأجهزة والأسماء البديلة', 'Search rooms, entities and aliases')}</span><input type="search" .value=${this.query} @input=${(event: Event) => this.query = (event.target as HTMLInputElement).value} placeholder=${this.tr('اكتب الاسم بالعربي أو الإنجليزي…', 'Type an Arabic or English name…')}></label><h4>${this.tr('الغرف', 'Rooms')}</h4><div class="results">${roomMatches.map(area => html`<button @click=${() => { this.ctx.selectRoom(area.area_id); this.ctx.closeSheet(); }}>${this.ctx.config.rooms[area.area_id]?.name || area.name}</button>`)}</div><h4>${this.tr('الأجهزة والمشاهد', 'Entities and scenes')}</h4><p class="hint">${this.tr('حتى ٨٠ نتيجة. وقت التحديث القديم لا يعني وحده أن الجهاز معطّل.', 'Up to 80 results. An old update timestamp alone does not mean a device is faulty.')}</p><div class="list">${matches.map(entity => html`<article><div class="row"><button class="entity" @click=${() => this.ctx.openEntity(entity.entity_id)}><strong>${nameOf(this.ctx.hass, entity.entity_id)}</strong><small>${entity.state} · ${this.tr('آخر تحديث: ', 'Updated: ')}${this.format(entity.last_updated)}</small></button><button class="star" aria-label=${this.tr('تبديل المفضلة', 'Toggle favorite')} aria-pressed=${favoriteIds(this.prefs).includes(entity.entity_id)} @click=${() => this.favorite(entity.entity_id)}>${favoriteIds(this.prefs).includes(entity.entity_id) ? '★' : '☆'}</button>${this.ctx.focusEntity ? html`<button class="subtle" @click=${() => this.ctx.focusEntity?.(entity.entity_id)}>${this.tr('على المخطط', 'On plan')}</button>` : nothing}</div>${this.admin ? html`<details><summary>${this.tr('أسماء بديلة وتأكيد الأمان', 'Aliases and safety confirmation')}</summary><label class="field"><span>${this.tr('أسماء البحث البديلة؛ افصلها بفاصلة', 'Search aliases; comma separated')}</span><input type="text" maxlength="400" .value=${(this.ctx.config.aliases?.[entity.entity_id] ?? []).join(', ')} @change=${(event: Event) => { const aliases = (event.target as HTMLInputElement).value.split(/[,،]/).map(value => value.trim().slice(0, 60)).filter(Boolean).slice(0, 8); this.ctx.saveLayout(config => { config.aliases ??= {}; config.aliases[entity.entity_id] = aliases; }); }}></label><label class="check"><input type="checkbox" .checked=${(this.exp.critical_entities ?? []).includes(entity.entity_id)} @change=${(event: Event) => { const checked = (event.target as HTMLInputElement).checked; this.updateExperience(exp => exp.critical_entities = checked ? [...new Set([...(exp.critical_entities ?? []), entity.entity_id])] : (exp.critical_entities ?? []).filter(id => id !== entity.entity_id)); }}>${this.tr('اطلب تأكيدًا قبل إطفاء هذا الجهاز', 'Confirm before turning this entity off')}</label></details>` : nothing}</article>`)}</div>`;
  }
  private renderAlerts() {
    const dnd = this.dndActive(); const all = this.alerts(); const alerts = all.filter(alert => (this.severity === "all" || this.severity === alert.severity) && (!dnd || alert.severity === "high"));
    return html`<h3>${this.tr("التنبيهات", "Notifications")}</h3>${dnd ? html`<p class="hint">${this.tr("عدم الإزعاج نشط. التنبيهات العادية مخفية حاليًا؛ التنبيهات المهمة تبقى ظاهرة.", "Do not disturb is active. Ordinary alerts are hidden; important alerts remain visible.")}</p>` : nothing}<label class="field"><span>${this.tr("الأهمية", "Priority")}</span>${this.fieldHelp("التسريب وتنبيهات السلامة والأبواب التي تجاوزت المهلة والطاقة تُعرض كتنبيهات مهمة.", "Leaks, safety sensors, overdue open doors and energy thresholds are important alerts.")}<select .value=${this.severity} @change=${(event: Event) => this.severity = (event.target as HTMLSelectElement).value}><option value="all">${this.tr("الكل", "All")}</option><option value="high">${this.tr("مهمة", "Important")}</option><option value="normal">${this.tr("عادية", "Ordinary")}</option></select></label>${alerts.length ? alerts.map(alert => html`<article class="row"><div><strong>${alert.severity === "high" ? "● " : ""}${alert.title}</strong><p>${alert.detail}</p>${alert.entity ? html`<small>${this.tr("آخر تحديث: ", "Updated: ")}${this.format(this.ctx.hass.states[alert.entity]?.last_updated)}</small>` : nothing}</div>${alert.id === "budget" ? html`<button @click=${() => { this.ctx.closeSheet(); window.dispatchEvent(new CustomEvent("sn-open-energy")); }}>${this.tr("مراجعة الطاقة", "Review energy")}</button>` : nothing}${alert.entity && this.ctx.hass.states[alert.entity] ? html`<button @click=${() => this.ctx.openEntity(alert.entity!)}>${this.tr("فتح", "Open")}</button>` : nothing}</article>`) : html`<p>${this.tr("لا توجد تنبيهات مطابقة الآن.", "No matching notifications right now.")}</p>`}${this.admin ? html`<label class="field"><span>${this.tr('تنبيه الباب المفتوح بعد (دقيقة)', 'Open-door alert after (minutes)')}</span><input type="number" min="1" max="1440" .value=${String(this.exp.door_open_minutes ?? 10)} @change=${(event: Event) => { const value = Number((event.target as HTMLInputElement).value); if (Number.isFinite(value) && value >= 1 && value <= 1440) this.updateExperience(exp => exp.door_open_minutes = value); }}></label><h4>${this.tr("عدم الإزعاج", "Do not disturb")}</h4><label class="check"><input type="checkbox" .checked=${!!this.exp.dnd?.enabled} @change=${(event: Event) => this.updateExperience(e => e.dnd = { start: e.dnd?.start ?? "22:00", end: e.dnd?.end ?? "07:00", enabled: (event.target as HTMLInputElement).checked })}>${this.tr("إخفاء التنبيهات العادية في الوقت المحدد", "Hide ordinary alerts during these hours")}</label><div class="grid">${(["start", "end"] as const).map(key => html`<label class="field"><span>${key === "start" ? this.tr("من", "From") : this.tr("حتى", "Until")}</span><input type="time" .value=${this.exp.dnd?.[key] ?? (key === "start" ? "22:00" : "07:00")} @change=${(event: Event) => this.updateExperience(e => { e.dnd ??= { enabled: false, start: "22:00", end: "07:00" }; e.dnd[key] = (event.target as HTMLInputElement).value; })}></label>`)}</div>` : nothing}`;
  }
  private renderMaintenance() {
    const tasks = this.exp.maintenance ?? [];
    const counters = this.entities.filter(entity => (entity.entity_id.startsWith('counter.') || entity.entity_id.startsWith('sensor.') && (['total','total_increasing'].includes(entity.attributes.state_class) || entity.attributes.device_class === 'duration')) && !['unknown', 'unavailable', ''].includes(entity.state) && Number.isFinite(Number(entity.state)));
    return html`<h3>${this.tr('صيانة البيت', 'Home maintenance')}</h3>${tasks.map(task => { const usage = maintenanceUsage(task, this.ctx.hass); return html`<article class="row"><div><strong>${task.title}</strong><p>${task.usage_entity ? usage ? `${usage.used.toFixed(1)} / ${task.usage_interval} ${usage.unit}` : this.tr('عداد الاستخدام غير متاح أو عاد للصفر؛ راجعه قبل اعتماد الموعد.', 'Usage counter unavailable or reset; review it before trusting the due point.') : task.due}${task.entity ? ' · ' + nameOf(this.ctx.hass, task.entity) : ''}</p>${task.usage_entity ? html`<small>${nameOf(this.ctx.hass, task.usage_entity)}</small>` : nothing}</div>${this.admin ? html`<button @click=${() => this.updateExperience(exp => { exp.maintenance = (exp.maintenance ?? []).flatMap(item => { if (item.id !== task.id) return [item]; if (item.usage_entity) { const entity = this.ctx.hass.states[item.usage_entity]; if (!entity || ['unavailable', 'unknown', ''].includes(entity.state) || !Number.isFinite(Number(entity.state))) return [item]; return [{ ...item, usage_baseline: Number(entity.state) }]; } if (!item.interval_days) return []; const due = new Date(); due.setDate(due.getDate() + item.interval_days); return [{ ...item, due: due.toISOString().slice(0, 10) }]; }); })}>${this.tr('تمت الصيانة', 'Mark complete')}</button>` : nothing}</article>`; })}${!tasks.length ? html`<p>${this.tr('لا توجد مهام صيانة مسجلة.', 'No maintenance tasks yet.')}</p>` : nothing}${this.admin ? html`<form @submit=${(event: Event) => { event.preventDefault(); if (!this.taskTitle.trim()) return; const entity = this.ctx.hass.states[this.taskUsageEntity]; if (this.taskUsageEntity && (!entity || ['unknown', 'unavailable', ''].includes(entity.state) || !Number.isFinite(Number(entity.state)) || !Number.isFinite(this.taskUsageInterval) || this.taskUsageInterval <= 0)) { this.error(new Error(this.tr('اختر عدادًا صالحًا ومقدار استخدام أكبر من صفر.', 'Choose a valid counter and positive usage interval.'))); return; } this.updateExperience(exp => { exp.maintenance ??= []; exp.maintenance.push({ id: crypto.randomUUID(), title: this.taskTitle.trim().slice(0, 120), entity: this.taskEntity || undefined, due: this.taskDue, interval_days: this.taskInterval || undefined, usage_entity: this.taskUsageEntity || undefined, usage_interval: this.taskUsageEntity ? this.taskUsageInterval : undefined, usage_baseline: this.taskUsageEntity ? Number(entity!.state) : undefined }); }); this.taskTitle = ''; }}><h4>${this.tr('تذكير جديد', 'New reminder')}</h4><label class="field"><span>${this.tr('اسم المهمة', 'Task title')}</span><input required type="text" maxlength="120" .value=${this.taskTitle} @input=${(event: Event) => this.taskTitle = (event.target as HTMLInputElement).value}></label><div class="grid"><label class="field"><span>${this.tr('تاريخ الاستحقاق', 'Due date')}</span><input required type="date" .value=${this.taskDue} @change=${(event: Event) => this.taskDue = (event.target as HTMLInputElement).value}></label><label class="field"><span>${this.tr('التكرار بالأيام؛ صفر لمرة واحدة', 'Repeat days; zero for once')}</span><input type="number" min="0" max="3650" .value=${String(this.taskInterval)} @change=${(event: Event) => this.taskInterval = Math.min(3650, Math.max(0, Number((event.target as HTMLInputElement).value)))}></label></div><label class="field"><span>${this.tr('عداد استخدام تراكمي بدل التاريخ (اختياري)', 'Cumulative usage counter instead of date (optional)')}</span>${this.entitySelect(this.taskUsageEntity, value => this.taskUsageEntity = value, counters.map(entity => entity.entity_id))}</label>${this.taskUsageEntity ? html`<label class="field"><span>${this.tr('ذكّرني بعد مقدار استخدام إضافي', 'Remind after additional usage')}</span><input type="number" min="0.01" step="any" .value=${String(this.taskUsageInterval)} @change=${(event: Event) => this.taskUsageInterval = Number((event.target as HTMLInputElement).value)}></label><p class="hint">${this.tr('اختر ساعات التشغيل أو عدادًا تراكميًا مناسبًا. لا نستنتج الاستخدام من تشغيل الجهاز وحده. يتجدد خط الأساس بعد إتمام الصيانة.', 'Choose runtime hours or an appropriate cumulative counter. Usage is not inferred from an on state. Marking complete resets the baseline.')}</p>` : nothing}<label class="field"><span>${this.tr('جهاز مرتبط (اختياري)', 'Related entity (optional)')}</span>${this.entitySelect(this.taskEntity, value => this.taskEntity = value)}</label><button>${this.tr('إضافة التذكير', 'Add reminder')}</button></form>` : nothing}`;
  }
  private renderPreferences() {
    const prefs = this.prefs; const order = prefs.page_order?.length ? prefs.page_order : ["home", "rooms", "climate", "lights", "robot", "family", "energy", "security", "media"];
    const labels: Record<string, string> = { home: this.tr("البيت", "Home"), rooms: this.tr("الغرف", "Rooms"), climate: this.tr("التكييف", "Climate"), lights: this.tr("الإضاءة", "Lights"), robot: this.tr("المكنسة", "Robot"), family: this.tr("العائلة", "Family"), energy: this.tr("الطاقة", "Energy"), security: this.tr("الأمان", "Security"), media: this.tr("الوسائط", "Media") };
    return html`<h3>${this.tr("تفضيلاتك", "Your preferences")}</h3><label class="field"><span>${this.tr("صفحة البداية لحسابك", "Your account start page")}</span>${this.fieldHelp("تتزامن مع شاشاتك الأخرى عند توفر الاتصال.", "Syncs to your other screens when connected.")}<select .value=${prefs.start_page ?? "home"} @change=${(event: Event) => this.updatePrefs({ start_page: (event.target as HTMLSelectElement).value })}>${Object.entries(labels).map(([id, label]) => html`<option value=${id} ?selected=${(prefs.start_page ?? "home") === id}>${label}</option>`)}</select></label><label class="field"><span>${this.tr("صفحة بداية خاصة بهذه الشاشة", "Start page for this screen only")}</span>${this.fieldHelp("مفيد لعرض المخطط على التابلت والمفضلة على الهاتف. هذا الاختيار يبقى على هذه الشاشة.", "Useful for a floor plan on the tablet and another page on your phone. This override stays on this screen.")}<select .value=${prefs.screen_start_page ?? ""} @change=${(event: Event) => this.updatePrefs({ screen_start_page: (event.target as HTMLSelectElement).value || undefined })}><option value="" ?selected=${!prefs.screen_start_page}>${this.tr("استخدم تفضيل الحساب", "Use account preference")}</option>${Object.entries(labels).map(([id, label]) => html`<option value=${id} ?selected=${prefs.screen_start_page === id}>${label}</option>`)}</select></label><label class="check"><input type="checkbox" .checked=${!!prefs.simple_mode} @change=${(event: Event) => this.updatePrefs({ simple_mode: (event.target as HTMLInputElement).checked })}>${this.tr("واجهة مبسّطة", "Simple interface")}</label>${this.fieldHelp("تقل التفاصيل الظاهرة مع بقاء الوظائف الأساسية متاحة.", "Reduces visible detail while keeping essential controls available.")}<label class="check"><input type="checkbox" .checked=${!!prefs.wall_display} @change=${(event: Event) => { savePreferences(this.ctx.hass, { wall_display: (event.target as HTMLInputElement).checked }, false); this.requestUpdate(); }}>${this.tr("شاشة حائط — أزرار أكبر وتعتيم ليلي", "Wall display — larger controls and night dimming")}</label><label class="check"><input type="checkbox" .checked=${!!prefs.high_contrast} @change=${(event: Event) => this.updatePrefs({ high_contrast: (event.target as HTMLInputElement).checked })}>${this.tr("تباين مرتفع", "High contrast")}</label><label class="field"><span>${this.tr("حجم النص", "Text size")}</span><select .value=${String(prefs.font_scale ?? 1)} @change=${(event: Event) => this.updatePrefs({ font_scale: Number((event.target as HTMLSelectElement).value) })}><option value="1">100%</option><option value="1.15">115%</option><option value="1.3">130%</option><option value="1.5">150%</option></select></label><h4>${this.tr('المفضلة وترتيبها', 'Favorites and their order')}</h4><label class="check"><input type="checkbox" .checked=${prefs.screen_favorites !== undefined} @change=${(event: Event) => { const checked = (event.target as HTMLInputElement).checked; savePreferences(this.ctx.hass, { screen_favorites: checked ? [...favoriteIds(prefs)] : undefined }, false); this.requestUpdate(); }}>${this.tr('مفضلة خاصة بهذه الشاشة؛ أوقفها لاستخدام مفضلة حسابك المتزامنة', 'Favorites for this screen only; turn off to use synced account favorites')}</label>${favoriteIds(prefs).map((id, index, list) => html`<div class="row"><span>${nameOf(this.ctx.hass, id)}</span><div><button ?disabled=${index === 0} aria-label=${this.tr('تقديم الجهاز', 'Move favorite earlier')} @click=${() => this.moveFavorite(index, -1)}>↑</button><button ?disabled=${index === list.length - 1} aria-label=${this.tr('تأخير الجهاز', 'Move favorite later')} @click=${() => this.moveFavorite(index, 1)}>↓</button></div></div>`)}<h4>${this.tr("ترتيب الصفحات", "Page order")}</h4><p class="hint">${this.tr("اسحب الصفحة لترتيبها، أو استخدم السهمين بلوحة المفاتيح أو على الهاتف.", "Drag pages to reorder, or use the arrow buttons with a keyboard or on a phone.")}</p><div role="list">${order.map((id: string, index: number) => html`<div class="row page-drag" role="listitem" draggable="true" @dragstart=${(event: DragEvent) => { this.draggedPage = id; event.dataTransfer?.setData("text/plain", id); if (event.dataTransfer) event.dataTransfer.effectAllowed = "move"; }} @dragend=${() => this.draggedPage = ""} @dragover=${(event: DragEvent) => { if (this.draggedPage) event.preventDefault(); }} @drop=${(event: DragEvent) => { event.preventDefault(); const source = this.draggedPage || event.dataTransfer?.getData("text/plain") || ""; this.movePage(source, id, order); }}><span>⋮⋮ ${labels[id] ?? id}</span><div><button class="subtle" ?disabled=${index === 0} aria-label=${this.tr("تقديم الصفحة", "Move page earlier")} @click=${() => { const next = [...order]; [next[index - 1], next[index]] = [next[index], next[index - 1]]; this.updatePrefs({ page_order: next }); }}>↑</button><button class="subtle" ?disabled=${index === order.length - 1} aria-label=${this.tr("تأخير الصفحة", "Move page later")} @click=${() => { const next = [...order]; [next[index + 1], next[index]] = [next[index], next[index + 1]]; this.updatePrefs({ page_order: next }); }}>↓</button></div></div>`)}</div>${this.admin ? html`<h4>${this.tr("جودة العرض والمخطط", "Display and floor-plan quality")}</h4><label class="field"><span>${this.tr("أداء الرسوم", "Graphics performance")}</span>${this.fieldHelp("التلقائي يختار جودة أخف للأجهزة محدودة الأداء. اختر خفيفًا للتابلت القديم.", "Auto chooses lighter rendering for limited devices. Choose light for older tablets.")}<select .value=${this.ctx.config.settings.performance ?? "auto"} @change=${(event: Event) => this.ctx.saveLayout(config => config.settings.performance = (event.target as HTMLSelectElement).value as "auto" | "light" | "high")}><option value="auto">${this.tr("تلقائي", "Auto")}</option><option value="light">${this.tr("خفيف", "Light")}</option><option value="high">${this.tr("جودة عالية", "High quality")}</option></select></label><label class="field"><span>${this.tr("عرض المخطط", "Floor-plan view")}</span>${this.fieldHelp("العرض الثنائي يظهر المخطط من الأعلى لتسهيل القراءة والتحكم.", "The 2D view shows your plan from above for easier reading and controls.")}<select .value=${this.ctx.config.settings.plan_view ?? "3d"} @change=${(event: Event) => this.ctx.saveLayout(config => config.settings.plan_view = (event.target as HTMLSelectElement).value as "2d" | "3d")}><option value="3d">${this.tr("ثلاثي الأبعاد", "3D")}</option><option value="2d">${this.tr("ثنائي الأبعاد", "2D")}</option></select></label>` : nothing}`;
  }
  private async importFile(event: Event) {
    const input = event.target as HTMLInputElement; const file = input.files?.[0]; input.value = ""; if (!file) return;
    await this.run(async () => {
      if (file.size > 1024 * 1024) throw new Error(this.tr("الملف أكبر من ١ ميغابايت.", "File is larger than 1 MB."));
      const raw = JSON.parse(await file.text());
      if (backupIssues(raw).length) throw new Error(this.tr("هذا الملف ليس نسخة إعدادات SmartNest صالحة.", "This is not a valid SmartNest configuration backup."));
      this.imported = normalize(raw);
    });
  }
  private restore(config: ProConfig) {
    if (!this.admin || !window.confirm(this.tr('تطبيق النسخة سيستبدل التصميم الحالي بعد حفظ نسخة قبله. متابعة؟', 'Apply this version after saving the current layout as a previous version?'))) return;
    void this.run(async () => { if (backupIssues(config).length) throw new Error(this.tr('النسخة غير متوافقة أو بياناتها غير سليمة.', 'The backup is incompatible or malformed.')); if (!this.ctx.restoreLayout) throw new Error(this.tr("أداة الاسترجاع غير متاحة؛ أعد تحميل الواجهة.", "Restore is unavailable; reload the dashboard.")); await this.ctx.restoreLayout(config); this.imported = undefined; this.notice = this.tr('تم الاسترجاع مع حفظ النسخة السابقة وسياسة الوصول الحالية.', 'Restored while retaining the previous version and current access policy.'); });
  }
  private comparison(config: ProConfig) {
    if (!this.admin) return this.adminOnly();
    const before = backupSummary(this.ctx.config), after = backupSummary(config);
    const missing = new Set(missingConfigEntities(config, this.ctx.hass.states));
    return html`<dl class="comparison">${(Object.keys(before) as (keyof typeof before)[]).map(key => html`<dt>${({ floors: this.tr('الطوابق', 'Floors'), rooms: this.tr('غرف المخطط', 'Plan rooms'), furniture: this.tr('الأثاث', 'Furniture'), favorites: this.tr('المفضلة', 'Favorites') })[key]}</dt><dd>${before[key]} → ${after[key]}</dd>`)}</dl><p>${this.tr('الاسم والمظهر: ', 'Name and theme: ')}${this.ctx.config.settings.home_name || 'SmartNest'} → ${config.settings.home_name || 'SmartNest'} · ${this.ctx.config.settings.theme} → ${config.settings.theme}</p><p class="hint">${this.tr('روابط أجهزة غير موجودة في البيت الحالي: ', 'Links not present in the current home: ')}${missing.size}${missing.size ? ' · ' + [...missing].slice(0, 12).join('، ') : ''}</p>`;
  }
  private renderBackup() {
    if (!this.admin) return this.adminOnly();
    return html`<h3>${this.tr("نسخ احتياطي واسترجاع", "Backup and restore")}</h3><p>${this.tr("الملف يحتوي تصميم بيتك وإعداداته. احفظه بشكل خاص؛ رمز قفل الشاشة لا يدخل الملف. الاسترجاع يستبدل التصميم وإعداداته بالكامل، مع إبقاء صلاحيات المستخدمين ورمز القفل الحاليين.", "The backup contains your home layout and settings. Keep it private; the screen PIN is excluded. Restore fully replaces layout settings while preserving current user-access rules and screen PIN.")}</p><button @click=${() => { const config = clone(this.ctx.config); delete config.settings.kiosk_pin; this.download("SmartNest-backup-" + new Date().toISOString().slice(0, 10) + ".json", config); }}>${this.tr("تنزيل نسخة احتياطية", "Download backup")}</button><label class="field upload"><span>${this.tr("استرجاع من ملف JSON؛ حتى ١ ميغابايت", "Restore JSON file; up to 1 MB")}</span><input type="file" accept=".json,application/json" @change=${this.importFile}></label>${this.imported ? html`<article><h4>${this.tr("معاينة النسخة المستوردة", "Imported backup preview")}</h4>${this.comparison(this.imported)}<button class="subtle" @click=${() => this.ctx.previewLayout?.(this.imported!)}>${this.tr("معاينة خاصة بدون حفظ", "Private preview without saving")}</button><button @click=${() => this.restore(this.imported!)}>${this.tr("تأكيد الاسترجاع", "Confirm restore")}</button><button class="subtle" @click=${() => this.imported = undefined}>${this.tr("إلغاء", "Cancel")}</button></article>` : nothing}<h4>${this.tr('تصاميم خاصة بهذه الشاشة', 'Private design variants on this screen')}</h4><p class="hint">${this.tr('حتى ٦ تصاميم محلية للمقارنة. لا تتزامن ولا تُنشر تلقائيًا، ولا تحتوي رمز القفل أو قواعد الوصول.', 'Up to 6 local variants for comparison. They do not sync or publish automatically, and exclude the PIN and access rules.')}</p><label class="field"><span>${this.tr('اسم التصميم', 'Variant name')}</span><input type="text" maxlength="80" .value=${this.variantName} @input=${(event: Event) => this.variantName = (event.target as HTMLInputElement).value}></label><button ?disabled=${!this.variantName.trim()} @click=${this.saveVariant}>${this.tr('حفظ التصميم الحالي', 'Save current variant')}</button>${this.variants.map(variant => html`<article><strong>${variant.name}</strong><small> · ${this.format(variant.at)}</small>${this.comparison(variant.config)}<button @click=${() => this.ctx.previewLayout?.(variant.config)}>${this.tr('معاينة بدون حفظ', 'Preview without saving')}</button><button class="subtle" @click=${() => this.restore(variant.config)}>${this.tr('اعتماد التصميم', 'Apply variant')}</button></article>`)}<h4>${this.tr("النسخ السابقة المحفوظة", "Saved previous versions")}</h4><button class="subtle" ?disabled=${this.busy} @click=${() => this.loadSection()}>${this.tr("تحديث السجل", "Refresh history")}</button>${this.versions.map(version => html`<div class="row"><span>${this.format(version.created_at)}</span><button @click=${() => this.restore(version.config)}>${this.tr("استرجاع", "Restore")}</button></div>`)}`;
  }
  private renderLicense() {
    const license = this.license; const remaining = license?.expires_at ? Math.ceil((license.expires_at * 1000 - Date.now()) / 86400000) : null;
    return html`<h3>${this.tr("ترخيص SmartNest", "SmartNest license")}</h3>${license ? html`<article><strong>${license.valid ? this.tr("الترخيص فعّال", "License active") : this.tr("يلزم التحقق من الترخيص", "License requires attention")}</strong>${license.customer_name ? html`<p>${license.customer_name}</p>` : nothing}<p>${this.tr("تاريخ الانتهاء: ", "Expires: ")}${license.expires_at === null ? this.tr("مدى الحياة", "Lifetime") : this.format(license.expires_at)}</p>${remaining !== null ? html`<p>${Math.max(0, remaining)} ${this.tr("يوم متبقٍ", "days remaining")}</p>${remaining <= 30 ? html`<p class="notice">${remaining <= 7 ? this.tr("اقترب الانتهاء جدًا؛ تواصل مع المزوّد للتجديد.", "Your license expires soon. Contact your provider to renew.") : this.tr("ترخيصك ينتهي خلال شهر. يمكنك التجديد بالمفتاح نفسه.", "Your license expires within a month. Renewal can retain the same key.")}</p>` : nothing}` : nothing}${license.offline_until ? html`<p class="hint">${this.tr("نهاية مهلة التحقق المحفوظة: ", "Cached validation deadline: ")}${this.format(license.offline_until)}</p>` : nothing}</article>` : html`<p>${this.tr("اضغط تحديث لقراءة حالة الترخيص.", "Refresh to read the license status.")}</p>`}<button ?disabled=${this.busy} @click=${() => this.loadSection()}>${this.tr("تحديث الحالة", "Refresh status")}</button><p><a href="https://smartnest.pro" target="_blank" rel="noopener noreferrer">${this.tr("التواصل مع SmartNest للتجديد والدعم", "Contact SmartNest for renewal and support")}</a></p><p class="hint">${this.tr("مفاتيح الترخيص وبيانات دخول Home Assistant لا تظهر هنا.", "License keys and Home Assistant credentials are never shown here.")}</p>`;
  }
  private chooseAccess(id: string) {
    this.accessUser = id; const current = this.ctx.config.access?.users[id]; this.childAccess = !!current?.child_mode; this.accessAreas = [...current?.areas ?? []]; this.accessEntities = [...current?.entities ?? []]; this.guestDays = current?.guest_until ? Math.max(0, Math.ceil((current.guest_until * 1000 - Date.now()) / 86400000)) : 0;
  }
  private renderAccess() {
    if (!this.admin) return this.adminOnly();
    const existing = this.ctx.config.access?.users ?? {};
    return html`<h3>${this.tr("صلاحيات العرض والتحكم داخل SmartNest", "SmartNest access preferences")}</h3><p class="hint">${this.tr("هذه قيود داخل SmartNest فقط. صلاحيات Home Assistant الأصلية تُدار من إعداداته ولا يغيرها هذا النموذج. ترك القائمتين فارغتين يمنع جميع الأجهزة لهذا الحساب داخل SmartNest. لإعادة الوصول غير المقيّد استخدم إزالة القيود.", "These are SmartNest restrictions only. Native Home Assistant permissions remain managed in Home Assistant. Leaving both lists empty denies all entities in SmartNest. Use Remove restrictions to restore unrestricted access.")}</p>${this.users.length ? html`<label class="field"><span>${this.tr("المستخدم", "User")}</span><select .value=${this.accessUser} @change=${(event: Event) => this.chooseAccess((event.target as HTMLSelectElement).value)}><option value="">${this.tr("اختر مستخدمًا", "Choose a user")}</option>${this.users.map(user => html`<option value=${user.id} ?selected=${this.accessUser === user.id}>${user.name}</option>`)}</select></label>` : html`<label class="field"><span>${this.tr("معرّف المستخدم من إعدادات Home Assistant", "User ID from Home Assistant settings")}</span><input type="text" .value=${this.accessUser} @change=${(event: Event) => this.chooseAccess((event.target as HTMLInputElement).value.trim())}></label>`}<div class="grid"><label class="field"><span>${this.tr("الغرف المسموحة؛ تحديد متعدد", "Allowed areas; multiple selection")}</span><select multiple size="6" @change=${(event: Event) => this.accessAreas = Array.from((event.target as HTMLSelectElement).selectedOptions).map(option => option.value)}>${areas(this.ctx.hass).map(area => html`<option value=${area.area_id} ?selected=${this.accessAreas.includes(area.area_id)}>${area.name}</option>`)}</select></label><label class="field"><span>${this.tr("أجهزة إضافية مسموحة", "Additional allowed entities")}</span><select multiple size="6" @change=${(event: Event) => this.accessEntities = Array.from((event.target as HTMLSelectElement).selectedOptions).map(option => option.value)}>${this.entities.map(entity => html`<option value=${entity.entity_id} ?selected=${this.accessEntities.includes(entity.entity_id)}>${nameOf(this.ctx.hass, entity.entity_id)}</option>`)}</select></label></div><label class="field"><span>${this.tr("صلاحية الضيف بالأيام؛ صفر بدون حد زمني", "Guest duration in days; zero for no deadline")}</span>${this.fieldHelp("المهلة لا تمنح أجهزة تلقائيًا؛ حدد الغرف أو الأجهزة المسموحة أعلاه.", "A deadline grants no entities by itself. Select allowed areas or entities above.")}<input type="number" min="0" max="365" .value=${String(this.guestDays)} @change=${(event: Event) => this.guestDays = Math.max(0, Math.min(365, Number((event.target as HTMLInputElement).value)))}></label><label class="check"><input type="checkbox" .checked=${this.childAccess} @change=${(event: Event) => this.childAccess = (event.target as HTMLInputElement).checked}>${this.tr("وضع أطفال: واجهة مبسطة ومنع أوامر الأقفال والإنذار والسكربتات والمشاهد الحساسة", "Child mode: simple interface and no lock, alarm, script or scene controls")}</label><button ?disabled=${!this.accessUser} @click=${() => { const user = this.accessUser; if (!user) return; this.ctx.saveLayout(config => { config.access ??= { users: {} }; config.access.users[user] = { areas: this.accessAreas.length ? [...this.accessAreas] : undefined, entities: this.accessEntities.length ? [...this.accessEntities] : undefined, guest_until: this.guestDays ? Math.floor(Date.now() / 1000) + this.guestDays * 86400 : undefined, child_mode: this.childAccess }; }); }}>${this.tr("تطبيق القيود", "Apply restrictions")}</button><h4>${this.tr("الحسابات المضبوطة", "Configured accounts")}</h4>${Object.entries(existing).map(([id, policy]) => html`<div class="row"><button class="entity" @click=${() => this.chooseAccess(id)}><strong>${this.users.find(user => user.id === id)?.name || id}</strong><small>${policy.guest_until ? this.format(policy.guest_until) : this.tr("بدون حد زمني", "No time limit")}</small></button><button class="subtle" @click=${() => { if (window.confirm(this.tr("إزالة قيود SmartNest لهذا الحساب؟", "Remove SmartNest restrictions for this account?"))) this.ctx.saveLayout(config => { if (config.access) delete config.access.users[id]; }); }}>${this.tr("إزالة القيود", "Remove restrictions")}</button></div>`)}`;
  }
  private renderActivity() {
    if (!this.admin) return this.adminOnly();
    return html`<h3>${this.tr("سجل أوامر SmartNest", "SmartNest activity")}</h3><p class="hint">${this.tr("يعرض الأوامر التي أُرسلت عبر SmartNest؛ قد توجد تغييرات أخرى من Home Assistant أو الأجهزة مباشرة.", "Shows actions sent through SmartNest. Other changes may come from Home Assistant or devices directly.")}</p><button ?disabled=${this.busy} @click=${() => this.loadSection()}>${this.tr("تحديث", "Refresh")}</button>${this.activity.length ? this.activity.map(event => html`<article><strong>${event.service === "state_changed" ? this.tr("تغيّر حالة جهاز", "Entity state changed") : event.domain + "." + event.service + " · " + (event.success ? event.confirmation === "confirmed" ? this.tr("حالة مؤكدة", "State confirmed") : event.confirmation === "unconfirmed" ? this.tr("الحالة لم تتأكد", "State unconfirmed") : this.tr("قُبل الطلب", "Request accepted") : this.tr("تعذّر", "Failed"))}</strong><p>${this.format(event.at)} · ${this.users.find(user => user.id === event.user)?.name || (event.user === "homeassistant" ? "Home Assistant" : event.user)}</p>${event.from_state !== undefined && event.to_state !== undefined ? html`<p dir="auto">${event.from_state} → ${event.to_state}</p>` : nothing}<small>${(event.entities ?? []).map(id => nameOf(this.ctx.hass, id)).join("، ")}</small></article>`) : html`<p>${this.tr("لا توجد أوامر مسجلة حتى الآن.", "No recorded actions yet.")}</p>`}`;
  }
  private renderSchedules() {
    if (!this.admin) return this.adminOnly();
    return html`<h3>${this.tr("جدولة المشاهد", "Schedule scenes")}</h3><p class="hint">${this.tr("التنفيذ يتم في Home Assistant حتى لو أغلقت الشاشة. اختر وقتًا مستقبليًا بالتوقيت المحلي لهذه الشاشة.", "Home Assistant runs the schedule even when this screen is closed. Choose a future time in this screen’s local time zone.")}</p><form @submit=${(event: Event) => { event.preventDefault(); void this.run(async () => { const date = new Date(this.scheduleAt); if (!this.scheduleEntity || !Number.isFinite(date.getTime()) || date.getTime() <= Date.now()) throw new Error(this.tr("اختر مشهدًا ووقتًا مستقبليًا صالحًا.", "Choose a scene and valid future time.")); await this.ctx.hass.callWS({ type: "smartnest_pro/schedule/add", entity_id: this.scheduleEntity, at: date.toISOString() }); this.notice = this.tr("تمت إضافة الجدولة.", "Schedule added."); await this.loadSection(); }); }}><label class="field"><span>${this.tr("المشهد أو السكربت", "Scene or script")}</span>${this.fieldHelp("اختر مشهدًا موجودًا ومُجرّبًا؛ سيعمل مرة واحدة في الموعد المحدد.", "Choose an existing, tested scene; it will run once at the selected time.")} ${this.entitySelect(this.scheduleEntity, value => this.scheduleEntity = value, this.sceneIds)}</label><label class="field"><span>${this.tr("موعد التنفيذ", "Run at")}</span><input required type="datetime-local" .value=${this.scheduleAt} @change=${(event: Event) => this.scheduleAt = (event.target as HTMLInputElement).value}></label><button ?disabled=${this.busy}>${this.tr("إضافة الجدولة", "Add schedule")}</button></form>${this.schedules.map(schedule => html`<div class="row"><div><strong>${nameOf(this.ctx.hass, schedule.entity_id)}</strong><p>${this.format(schedule.at)}</p></div><button class="subtle" ?disabled=${this.busy} @click=${() => this.run(async () => { await this.ctx.hass.callWS({ type: "smartnest_pro/schedule/cancel", id: schedule.id }); await this.loadSection(); })}>${this.tr("إلغاء", "Cancel")}</button></div>`)}`;
  }
  private renderEnergy() {
    const rate = tariffAt(new Date(), this.exp.tariff, this.exp.tariff_schedule);
    return html`<h3>${this.tr("ميزانية الطاقة والتعرفة", "Energy budget and tariff")}</h3><p class="hint">${this.tr("التكلفة تقديرية من الاستهلاك المسجل، وليست فاتورة. التعرفة المتغيرة تطبق على ساعات Recorder الفعلية؛ لا نستنتج سجل الشهر من القدرة الحالية.", "Costs are estimates from recorded consumption, not a bill. Variable tariffs use actual recorder hours; monthly history is not inferred from current power.")}</p>${this.admin ? html`<label class="field"><span>${this.tr("حساس قدرة البيت", "Home power sensor")}</span>${this.entitySelect(this.exp.power_entity ?? "", value => this.updateExperience(exp => exp.power_entity = value || undefined), this.entities.filter(entity => entity.attributes.device_class === "power").map(entity => entity.entity_id))}</label><div class="grid">${([['tariff', this.tr('التعرفة الأساسية لكل kWh', 'Base price per kWh'), 0.01], ['monthly_budget', this.tr('الميزانية الشهرية', 'Monthly budget'), 1], ['power_alert_kw', this.tr('تنبيه قدرة أعلى من (kW)', 'Power alert above (kW)'), 0.1]] as const).map(([key, label, step]) => html`<label class="field"><span>${label}</span><input type="number" min="0" step=${step} .value=${String(this.exp[key] ?? '')} @change=${(event: Event) => { const input = event.target as HTMLInputElement; const value = input.value === '' ? undefined : Number(input.value); if (value !== undefined && (!Number.isFinite(value) || value < 0)) return; this.updateExperience(exp => exp[key] = value); }}></label>`)}<label class="field"><span>${this.tr('رمز العملة', 'Currency')}</span><input type="text" maxlength="8" .value=${this.exp.currency ?? '₪'} @change=${(event: Event) => this.updateExperience(exp => exp.currency = (event.target as HTMLInputElement).value.trim().slice(0, 8))}></label></div><h4>${this.tr('تعرفة حسب الساعة', 'Time-of-use tariff')}</h4><p class="hint">${this.tr('الأوقات بتوقيت هذه الشاشة، بحدود ساعة كاملة. الفترة يمكن أن تعبر منتصف الليل. لا يسمح بتداخل الفترات؛ باقي الساعات تستخدم التعرفة الأساسية.', 'Times use this screen’s time zone and whole-hour boundaries. A period may cross midnight. Overlaps are rejected; other hours use the base tariff.')}</p>${(this.exp.tariff_schedule ?? []).map((slot, index) => html`<div class="row"><span>${slot.start} → ${slot.end} · ${slot.rate} ${this.exp.currency ?? ''}/kWh</span><button class="subtle" @click=${() => this.updateExperience(exp => exp.tariff_schedule = (exp.tariff_schedule ?? []).filter((_, i) => i !== index))}>${this.tr('إزالة الفترة', 'Remove period')}</button></div>`)}<form @submit=${(event: Event) => { event.preventDefault(); const next = [...(this.exp.tariff_schedule ?? []), { start: this.tariffStart, end: this.tariffEnd, rate: this.tariffRate }]; if (!validTariffSchedule(next)) { this.error(new Error(this.tr('الفترات تتداخل أو الوقت غير مضبوط على ساعة كاملة أو السعر غير صالح.', 'Periods overlap, a time is not on a whole-hour boundary, or the rate is invalid.'))); return; } this.updateExperience(exp => exp.tariff_schedule = next); }}><div class="grid"><label class="field"><span>${this.tr('من', 'From')}</span><input type="time" step="3600" required .value=${this.tariffStart} @change=${(event: Event) => this.tariffStart = (event.target as HTMLInputElement).value}></label><label class="field"><span>${this.tr('حتى', 'Until')}</span><input type="time" step="3600" required .value=${this.tariffEnd} @change=${(event: Event) => this.tariffEnd = (event.target as HTMLInputElement).value}></label><label class="field"><span>${this.tr('سعر kWh خلال الفترة', 'Price per kWh in period')}</span><input type="number" min="0" step="0.001" required .value=${String(this.tariffRate)} @change=${(event: Event) => this.tariffRate = Number((event.target as HTMLInputElement).value)}></label></div><button>${this.tr('إضافة فترة', 'Add tariff period')}</button></form>` : nothing}<h4>${this.tr('القدرة الآن', 'Power right now')}</h4>${this.entities.filter(entity => entity.attributes.device_class === 'power' && powerKw(entity) != null).map(entity => html`<div class="row"><span>${nameOf(this.ctx.hass, entity.entity_id)}</span><strong>${powerKw(entity)!.toFixed(2)} kW${rate !== undefined ? ' · ' + (Math.max(0, powerKw(entity)!) * rate).toFixed(2) + ' ' + (this.exp.currency ?? '') + this.tr('/ساعة', '/hour') : ''}</strong></div>`)}`;
  }
  private async checkConnection() {
    await this.run(async () => {
      const started = performance.now(); let timer: ReturnType<typeof setTimeout> | undefined;
      try {
        const response = await Promise.race([
          this.ctx.hass.callWS<{ valid: boolean }>({ type: "smartnest_pro/license/status" }),
          new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new Error(this.tr("انتهت مهلة الاتصال بعد ١٠ ثوانٍ.", "Connection timed out after 10 seconds."))), 10_000); }),
        ]);
        if (!response || typeof response.valid !== "boolean") throw new Error(this.tr("استجابة الاتصال غير متوقعة.", "Unexpected connection response."));
        this.connectionResult = { checkedAt: new Date().toISOString(), ok: true, latency: Math.round(performance.now() - started), validLicense: response.valid };
      } catch (error) {
        this.connectionResult = { checkedAt: new Date().toISOString(), ok: false }; throw error;
      } finally { clearTimeout(timer); }
    });
  }
  private diagnostics() {
    const report = { product: "SmartNest Pro", version: __SN_VERSION__, generated_at: new Date().toISOString(), language: this.ctx.lang, entity_count: this.entities.length, area_count: areas(this.ctx.hass).length, unavailable_count: this.entities.filter(e => ["unknown", "unavailable"].includes(e.state)).length, missing_link_count: this.missingLinks().length, floor_count: this.ctx.config.plan.floors.length, theme: this.ctx.config.settings.theme, connection: this.connectionResult ? { checked_at: this.connectionResult.checkedAt, reachable: this.connectionResult.ok, round_trip_ms: this.connectionResult.latency ?? null } : null };
    return html`<h4>${this.tr("تشخيص الاتصال", "Diagnostics")}</h4><button ?disabled=${this.busy} @click=${this.checkConnection}>${this.tr("فحص الاتصال الآن", "Check connection now")}</button>${this.connectionResult ? html`<p role="status">${this.connectionResult.ok ? this.tr("وصل رد فعلي من Home Assistant", "Home Assistant responded") + " · " + this.connectionResult.latency + " ms" : this.tr("تعذّر وصول رد من Home Assistant.", "Home Assistant did not respond.")} · ${this.format(this.connectionResult.checkedAt)}</p>${this.connectionResult.ok && !this.connectionResult.validLicense ? html`<p class="hint">${this.tr("الاتصال يعمل، لكن الترخيص يحتاج إلى تحقق.", "The connection works, but the license needs attention.")}</p>` : nothing}` : nothing}<p>SmartNest Pro ${__SN_VERSION__} · ${report.entity_count} ${this.tr("جهاز", "entities")} · ${report.area_count} ${this.tr("غرفة", "areas")}</p><p>${report.unavailable_count} ${this.tr("غير متصلة", "unavailable")} · ${report.missing_link_count} ${this.tr("روابط مفقودة", "missing links")}</p><h4>${this.tr('فحوص وإجراءات مقترحة', 'Checks and suggested actions')}</h4>${this.missingLinks().length ? html`<article><strong>${this.tr('روابط أجهزة مفقودة', 'Missing entity links')}</strong><p>${this.missingLinks().slice(0, 20).join('، ')}</p><p>${this.tr('افتح إعدادات الغرفة أو قطعة الأثاث وحدد الكيان البديل. لا تسترجع نسخة قديمة قبل مراجعة الروابط.', 'Open the room or furniture settings and select the replacement entity. Review links before restoring an older design.')}</p></article>` : html`<p>✓ ${this.tr('روابط التصميم الموجودة تشير إلى كيانات حالية.', 'Existing layout links point to current entities.')}</p>`}${this.entities.filter(entity => ['unavailable', 'unknown'].includes(entity.state)).slice(0, 12).map(entity => html`<article><strong>${nameOf(this.ctx.hass, entity.entity_id)}</strong><p>${this.contextDetail(entity.entity_id, this.tr('افحص طاقة الجهاز، الشبكة ثم صفحة التكامل في Home Assistant. وقت تحديث قديم وحده لا يكفي لتشخيص عطل.', 'Check device power, network, then its integration in Home Assistant. An old update time alone is not enough to diagnose failure.'))}</p><button class="subtle" @click=${() => this.ctx.openEntity(entity.entity_id)}>${this.tr('فتح الجهاز', 'Open entity')}</button></article>`)}<button @click=${() => this.supportPreview = report}>${this.tr('معاينة تقرير الدعم', 'Preview support report')}</button>${this.supportPreview ? html`<article><h4>${this.tr('راجع التقرير قبل تنزيله', 'Review before downloading')}</h4><pre>${JSON.stringify(this.supportPreview, null, 2)}</pre><button @click=${() => this.download('SmartNest-support.json', this.supportPreview)}>${this.tr('تنزيل هذا التقرير', 'Download this report')}</button><button class="subtle" @click=${() => this.supportPreview = undefined}>${this.tr('إغلاق المعاينة', 'Close preview')}</button></article>` : nothing}<p class="hint">${this.tr("التقرير يضم أعدادًا وإصدارًا فقط؛ بدون أسماء الأجهزة أو معرّفاتها أو المخطط أو رموز الدخول.", "The report contains counts and version only, with no entity names, IDs, layout or credentials.")}</p>`;
  }
  private renderHelp() {
    const steps = [this.tr("ابدأ بالإعداد الأول لاختيار اسم البيت واللغة والأجهزة الأساسية.", "Start with setup to choose the home name, language and key entities."), this.tr("افتح تعديل المخطط واربط كل غرفة بمنطقة Home Assistant، ثم احفظ التصميم.", "Edit the floor plan, link rooms to Home Assistant areas, and save your layout."), this.tr("أضف مفضلتك واحفظ نسخة احتياطية. اضغط مطولًا على الجهاز لخياراته الإضافية.", "Choose favorites and download a backup. Hold an entity for additional controls.")];
    return html`<h3>${this.tr("مساعدة وجولة سريعة", "Help and quick tour")}</h3><article><strong>${this.tourStep + 1} / 3</strong><p>${steps[this.tourStep]}</p><button ?disabled=${this.tourStep === 0} class="subtle" @click=${() => this.tourStep--}>${this.tr("السابق", "Previous")}</button><button ?disabled=${this.tourStep === 2} @click=${() => this.tourStep++}>${this.tr("التالي", "Next")}</button></article>${this.admin ? html`<button @click=${() => { this.ctx.closeSheet(); window.dispatchEvent(new CustomEvent("sn-open-setup")); }}>${this.tr("فتح إعداد أول تشغيل", "Open first-run setup")}</button>` : nothing}<details><summary>${this.tr("الجهاز لا يستجيب", "An entity does not respond")}</summary><p>${this.tr("افتح التنبيهات، تحقق من حالة الجهاز وآخر تحديث له، ثم جرّبه من Home Assistant. لا تكرر الضغط أثناء تنفيذ الأمر.", "Check notifications and the entity’s state and update time, then try it from Home Assistant. Avoid repeated presses during an action.")}</p></details><details><summary>${this.tr("كيف أحافظ على التصميم؟", "How do I protect my layout?")}</summary><p>${this.tr("من النسخ الاحتياطي يمكنك تنزيل ملف واسترجاعه بعد المعاينة، أو العودة لنسخة سابقة. احفظ تعديلاتك قبل إغلاق وضع التعديل.", "Download a backup and restore it after reviewing the preview, or restore a previous saved version. Save edits before leaving edit mode.")}</p></details><details><summary>${this.tr("كيف أجدد الترخيص؟", "How do I renew?")}</summary><p>${this.tr("افتح ترخيصي لمعرفة موعد الانتهاء، وتواصل مع المزوّد. يمكنه تمديد نفس المفتاح بدون تغيير التصميم.", "Open My license for the expiry date and contact your provider. They can extend the same key without changing your layout.")}</p></details>${this.admin ? html`<h4>${this.tr("نسخ إعدادات غرفة", "Copy room settings")}</h4><p class="hint">${this.tr("ينسخ إعدادات الغرفة وروابط حسّاساتها؛ راجع الأجهزة المرتبطة بعد النسخ.", "Copies room settings and sensor links. Review linked entities after copying.")}</p><div class="grid">${(["from", "to"] as const).map(kind => html`<label class="field"><span>${kind === "from" ? this.tr("من غرفة", "From room") : this.tr("إلى غرفة", "To room")}</span><select .value=${kind === "from" ? this.copyFrom : this.copyTo} @change=${(event: Event) => { if (kind === "from") this.copyFrom = (event.target as HTMLSelectElement).value; else this.copyTo = (event.target as HTMLSelectElement).value; }}><option value="">—</option>${areas(this.ctx.hass).map(area => html`<option value=${area.area_id} ?selected=${(kind === "from" ? this.copyFrom : this.copyTo) === area.area_id}>${area.name}</option>`)}</select></label>`)}</div><button ?disabled=${!this.copyFrom || !this.copyTo || this.copyFrom === this.copyTo} @click=${() => { if (window.confirm(this.tr("استبدال إعدادات الغرفة المستهدفة؟", "Replace the target room settings?"))) this.ctx.saveLayout(config => { const previousName = config.rooms[this.copyTo]?.name; config.rooms[this.copyTo] = { ...clone(config.rooms[this.copyFrom] ?? {}), name: previousName }; }); }}>${this.tr("نسخ الإعدادات", "Copy settings")}</button>` : nothing}${this.diagnostics()}`;
  }
  private adminOnly() { return html`<p>${this.tr("هذه الأدوات متاحة لمسؤول المنزل فقط.", "These tools are available to home administrators only.")}</p>`; }
  render() {
    if (!this.ctx) return nothing;
    const tabs: [Section, string][] = [["overview", this.tr("الملخص", "Overview")], ["search", this.tr("البحث", "Search")], ["alerts", this.tr("التنبيهات", "Alerts")], ["maintenance", this.tr("الصيانة", "Maintenance")], ["preferences", this.tr("تفضيلاتي", "Preferences")], ["energy", this.tr("الطاقة", "Energy")], ["license", this.tr("ترخيصي", "My license")], ["backup", this.tr("النسخ الاحتياطي", "Backups")], ["access", this.tr("الصلاحيات", "Access")], ["activity", this.tr("السجل", "Activity")], ["schedules", this.tr("الجدولة", "Schedules")], ["help", this.tr("المساعدة", "Help")]];
    const renderers: Record<Section, () => unknown> = { overview: () => this.renderOverview(), search: () => this.renderSearch(), alerts: () => this.renderAlerts(), maintenance: () => this.renderMaintenance(), preferences: () => this.renderPreferences(), backup: () => this.renderBackup(), license: () => this.renderLicense(), access: () => this.renderAccess(), activity: () => this.renderActivity(), schedules: () => this.renderSchedules(), energy: () => this.renderEnergy(), help: () => this.renderHelp() };
    return html`<div dir=${this.ctx.rtl ? "rtl" : "ltr"}><nav aria-label=${this.tr("أقسام مركز البيت", "Home center sections")}>${tabs.filter(([id]) => this.admin || !["backup", "access", "activity", "schedules"].includes(id)).map(([id, title]) => html`<button aria-pressed=${this.section === id} @click=${() => this.changeSection(id)}>${title}</button>`)}</nav>${this.busy ? html`<p role="status" class="hint">${this.tr("جارٍ تنفيذ الطلب…", "Working…")}</p>` : nothing}${this.notice ? html`<p role=${this.failed ? "alert" : "status"} class="notice">${this.notice}</p>` : nothing}<section>${renderers[this.section]()}</section></div>`;
  }
  static styles = [shared, fieldStyles, css`
    pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;direction:ltr;text-align:left;max-height:300px;overflow:auto}.comparison{display:grid;grid-template-columns:1fr auto;gap:8px;font-size:12px}.comparison dd{margin:0;direction:ltr}.check{display:flex;gap:9px;align-items:center;margin:14px 0}.check input{width:18px;height:18px;min-height:18px}
    :host{display:block;color:var(--sn-text);font-family:var(--sn-font)}nav{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:24px}button{font:inherit;cursor:pointer;color:var(--sn-text);background:var(--sn-glass-light);border:1px solid var(--sn-glass-border);padding:10px 14px;border-radius:12px}button:hover,button[aria-pressed=true]{background:var(--sn-chip);border-color:var(--sn-accent)}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--sn-accent);outline-offset:3px}h3{font-size:20px;margin:0 0 18px}h4{font-size:15px;margin:18px 0 12px}p{line-height:1.8;font-size:13px}a{color:var(--sn-accent)}small,.hint{color:var(--sn-text-dim);font-size:12px;line-height:1.7}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px}.metrics>div,article{padding:16px;background:var(--sn-glass-light);border:1px solid var(--sn-glass-border);border-radius:15px;margin-bottom:12px}.metrics strong{display:block;font-size:25px}.metrics span{font-size:12px;color:var(--sn-text-dim)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px;border-bottom:1px solid var(--sn-glass-border)}.row p{margin:6px 0}.entity{background:transparent;border:0;text-align:start;display:grid;gap:6px;min-width:0;overflow-wrap:anywhere}.field-help{display:block;margin:2px 0 8px}.page-drag{cursor:grab}.star{font-size:24px;color:var(--sn-accent)}.results{display:flex;gap:8px;flex-wrap:wrap}.subtle{background:transparent}.notice{padding:12px;border:1px solid var(--sn-accent);border-radius:12px;background:var(--sn-glass-light)}input[type=search],input[type=date],input[type=time],input[type=datetime-local]{width:100%;min-height:44px;padding:10px;border:1px solid var(--sn-glass-border);background:var(--sn-glass-light);border-radius:12px;color:var(--sn-text);font:inherit}select[multiple]{height:auto;min-height:120px}.upload{margin-top:24px}details{border-bottom:1px solid var(--sn-glass-border);padding:14px 0}summary{cursor:pointer;font-size:14px}@media(max-width:620px){.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}nav button{font-size:12px;padding:8px 10px}.row{align-items:flex-start}.row>div{min-width:0}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
  `];
}
